            <input id="task-title" name="title" type="text" autocomplete="off">
            <button type="submit">Create task</button>
          </div>
          <p id="task-alert" class="alert" role="alert" hidden></p>
        </form>
        <label for="default-task-priority">Default task priority</label>
        <select id="default-task-priority">
          <option>Low</option>
          <option selected>Normal</option>
          <option>High</option>
        </select>
        <label for="task-filter">Task filter</label>
        <select id="task-filter">
          <option>All</option>
          <option>Open</option>
          <option>Completed</option>
        </select>
        <label for="priority-filter">Priority filter</label>
        <select id="priority-filter">
          <option>All</option>
          <option>Low</option>
          <option>Normal</option>
          <option>High</option>
        </select>
        <p id="task-rename-alert" class="alert" role="alert" hidden></p>
        <p id="task-date-alert" class="alert" role="alert" hidden></p>
        <div id="tasks" class="tasks" aria-live="polite"></div>
      </section>
    </main>
    <script type="module" src="/app.js"></script>
  </body>
</html>
:root {
  color: #172033;
  background: #f5f7fb;
  font-family: system-ui, sans-serif;
  font-synthesis: none;
}

* { box-sizing: border-box; }

body { margin: 0; }

.container {
  width: min(720px, calc(100% - 32px));
  margin: 56px auto;
  padding: 32px;
  background: white;
  border: 1px solid #e1e6ef;
  border-radius: 12px;
}

h1 { margin: 0 0 28px; }

label { display: block; margin-bottom: 8px; font-weight: 600; }

.create-row, .project-row { display: flex; gap: 12px; align-items: center; }

input {
  min-width: 0;
  flex: 1;
  padding: 10px 12px;
  border: 1px solid #aeb8c9;
  border-radius: 6px;
  font: inherit;
}

button {
  padding: 10px 14px;
  border: 0;
  border-radius: 6px;
  background: #2457c5;
  color: white;
  font: inherit;
  cursor: pointer;
}

button:focus-visible, input:focus-visible { outline: 3px solid #88aaff; outline-offset: 2px; }

.projects { display: grid; gap: 10px; margin-top: 24px; }
.tasks { display: grid; gap: 10px; margin-top: 16px; }

.project-row {
  justify-content: space-between;
  padding: 12px 14px;
  border: 1px solid #e1e6ef;
  border-radius: 8px;
}

.task-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 12px 14px;
  border: 1px solid #e1e6ef;
  border-radius: 8px;
}

.task-row input { flex: 0 0 auto; width: 18px; height: 18px; }

#task-filter { padding: 8px 10px; border: 1px solid #aeb8c9; border-radius: 6px; font: inherit; }

.alert { margin: 8px 0 0; color: #b42318; }

#back-to-projects { margin-bottom: 24px; }

[hidden] { display: none !important; }

@media (max-width: 480px) {
  .container { margin: 24px auto; padding: 22px; }
  .create-row { align-items: stretch; flex-direction: column; }
}

.task-rename-form { display: flex; flex: 1; gap: 8px; align-items: center; }
.task-rename-form input { padding: 7px 9px; }
.task-due-date-form { display: flex; gap: 8px; align-items: center; }
.task-due-date-form input { flex: 0 1 145px; padding: 7px 9px; }
.task-row > span { min-width: 0; }
@media (max-width: 600px) {
  .task-row { flex-wrap: wrap; }
  .task-rename-form { flex-basis: 100%; order: 3; }
}
